            abi.decode(payload, (address, uint256, bytes, bytes32, bytes32, uint256));
    } else {
        // Decode the data in the scheduleBatch function
        (targets, , callDatas, , , ) =
        abi.decode(payload, (address[], uint256[], bytes[], bytes32, bytes32, uint256));
    }

    // Traverse all the schedule targets and selectors extracted from calldatas
