    /// @return Pool address.
    function getV3Pool(address factory, address[] memory tokens, int24 tickSpacing)
        public
        view
        virtual
        override
        returns (address)
    {
        return ICLFactory(factory).getPool(tokens[0], tokens[1], tickSpacing);
    }
}

