            // Cap at 10000 BPS (100%) to prevent over-distribution.
            if (shareBPS_ > 10000) {
                shareBPS_ = 10000;
            }

            _purchaseShares[purchaseId_][contributor_] = shareBPS_;
            purchase_.contributors.push(contributor_);
        }
    }

    // 8. Emit event.
    emit PurchaseRecorded(
        purchaseId_,
        collection_,
        tokenId_,
        costETH_,
        purchase_.contributors.length
